[1376] = "Alle Tags",
-- 08c83906 English: Edit the description, tags, author, realm, email, website and version. Source
--     citations remain separate from your attribution. Use changes updates the rotation draft;
--     Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values.
[1377] = "Beschreibung, Tags, Autor, Realm, E-Mail, Website und Version bearbeiten. Quellenangaben bleiben von Ihren Urheberangaben getrennt. Änderungen verwenden aktualisiert den Rotationsentwurf; die Rotation übernehmen, um sie zu speichern. Abbrechen oder Escape stellt die Werte beim Öffnen dieses Dialogs wieder her.",
-- 73f5fe1e English: Invalid tags. Use up to 64 tags of 64 characters, separated by commas.
[1378] = "Ungültige Tags. Bis zu 64 Tags mit je 64 Zeichen verwenden, durch Kommas getrennt.",
-- 36b7b9b3 English: Separate tags with commas. Use quotes for tags containing commas. Any personal
--     label is allowed.
[1379] = "Tags durch Kommas trennen. Tags, die Kommas enthalten, in Anführungszeichen setzen. Jede persönliche Bezeichnung ist erlaubt.",
-- 1331275b English: Tags
[1380] = "Tags",
-- 1dd4ab9e English: Switch priority
[1381] = "Wechselpriorität",
-- 1e51f6c3 English: Priority %d
[1382] = "Priorität %d",
-- defa7982 English: Invalid priority
[1383] = "Ungültige Priorität",
-- 1501b340 English: Switch priority must be a whole number between -100000 and 100000.
[1384] = "Die Wechselpriorität muss eine ganze Zahl zwischen -100000 und 100000 sein.",
-- f3967731 English: Edit the description, tags, switch priority, author, realm, email, website and
--     version. Source citations remain separate from your attribution. Use changes updates the
--     rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s
--     opening values.
[1385] = "Beschreibung, Tags, Wechselpriorität, Autor, Realm, E-Mail, Website und Version bearbeiten. Quellenangaben bleiben von Ihren Urheberangaben getrennt. Änderungen verwenden aktualisiert den Rotationsentwurf; die Rotation übernehmen, um sie zu speichern. Abbrechen oder Escape stellt die Werte beim Öffnen dieses Dialogs wieder her.",
-- a37462ad English: Higher numbers are tried first; your rotations and Built Ins compete on
--     priority alone. The fallback is used only when no other rotation matches. Equal priorities
--     use name, then identity. Blank means zero.
[1386] = "Höhere Zahlen werden zuerst probiert; Ihre Rotationen und die integrierten konkurrieren allein über die Priorität. Die Ersatzrotation wird nur verwendet, wenn keine andere Rotation passt. Bei gleicher Priorität entscheiden der Name und danach die Identität. Leer bedeutet null.",
-- 2040fdbd English: Invalid switch priority for %s:%s; explicit repair resets it to zero.
[1387] = "Ungültige Wechselpriorität für %s:%s; eine ausdrückliche Reparatur setzt sie auf null zurück.",
