[1553] = "Ungültiges Feldschema: %s",
-- 76900f1b English: Back
[1554] = "Zurück",
-- 02dbfe6e English: Named fields. Choose a type, then edit its children for nested data.
[1555] = "Benannte Felder. Einen Typ wählen und dann für verschachtelte Daten seine Unterelemente bearbeiten.",
-- 8eba81e3 English: Allowed types. A nested record or type list describes each item in a list.
[1556] = "Erlaubte Typen. Ein verschachtelter Datensatz oder eine Typliste beschreibt jedes Element einer Liste.",
-- 130a1408 English: Showing the first 200 fields. Use Advanced schema for larger definitions.
[1557] = "Es werden die ersten 200 Felder angezeigt. Für größere Definitionen das erweiterte Schema verwenden.",
-- 5f42d901 English: Add field
[1558] = "Feld hinzufügen",
-- cb4190b5 English: Tag color
[1559] = "Tagfarbe",
-- 08b91fc6 English: Type a tag and press Enter, or choose an existing tag. Click a tag to remove
--     it; use the search results to change tag colors.
[1560] = "Einen Tag eingeben und die Eingabetaste drücken oder einen vorhandenen Tag wählen. Auf einen Tag klicken, um ihn zu entfernen; Tagfarben über die Suchergebnisse ändern.",
-- cbf6490e English: Search existing tags and select any number of them. Click a selected tag to
--     remove it; use the search results to change tag colors.
[1561] = "Vorhandene Tags durchsuchen und beliebig viele davon auswählen. Auf einen ausgewählten Tag klicken, um ihn zu entfernen; Tagfarben über die Suchergebnisse ändern.",
-- 45fa2eb3 English: Click to remove this tag. Use the search results to change tag colors.
[1562] = "Klicken, um diesen Tag zu entfernen. Tagfarben über die Suchergebnisse ändern.",
-- 84cfb5be English: Each callback keeps its own pending text while switching tabs. Undo and Redo
--     edit that callback buffer. Reset restores its last saved code, or the template for a new
--     condition, and can be undone. The main Apply saves and registers all callback buffers and
--     metadata; Discard drops the whole draft. Leaving with changes offers Apply, Discard or
--     Cancel. Check syntax runs no callbacks.
[1563] = "Jeder Callback behält beim Wechseln der Reiter seinen eigenen ausstehenden Text. Rückgängig und Wiederherstellen bearbeiten den Puffer dieses Callbacks. Zurücksetzen stellt seinen zuletzt gespeicherten Code oder bei einer neuen Bedingung die Vorlage wieder her und kann rückgängig gemacht werden. Das Haupt-Übernehmen speichert und registriert alle Callback-Puffer und Metadaten; Verwerfen verwirft den gesamten Entwurf. Beim Verlassen mit Änderungen werden Übernehmen, Verwerfen oder Abbrechen angeboten. Syntax prüfen führt keine Callbacks aus.",
-- 047aff36 English: No native Lua editor has been opened this session.
[1564] = "In dieser Sitzung wurde noch kein nativer Lua-Editor geöffnet.",
-- 5472dd28 English: Lua input diagnostics
[1565] = "Lua-Eingabediagnose",
-- 5c126363 English: Native input test
[1566] = "Test der nativen Eingabe",
-- 6043d2ec English: Input test
[1567] = "Eingabetest",
-- 5a832570 English: Stock font
[1568] = "Standardschrift",
-- d92ba9ef English: RM font
[1569] = "RM-Schrift",
-- c7b373e3 English: Click the sample, then try Up/Down and look for the caret. Compare Stock font
--     and RM font. This temporary text is not saved.
[1570] = "Auf das Beispiel klicken, dann Hoch/Runter ausprobieren und auf die Einfügemarke achten. Standardschrift und RM-Schrift vergleichen. Dieser temporäre Text wird nicht gespeichert.",
-- 90364218 English: Arrow test
[1571] = "Pfeiltest",
-- 19a006ce English: Arrows: on
[1572] = "Pfeile: an",
-- 423c677c English: Arrows
[1573] = "Pfeile",
-- 170322a3 English: Info
[1574] = "Info",
-- 9ee41d20 English: Show input diagnostics for this open Lua editor.
[1575] = "Eingabediagnose für diesen geöffneten Lua-Editor anzeigen.",
-- 6ecc3df6 English: Move
[1576] = "Verschieben",
-- 9e3bd238 English: Edit fields opens a graphical schema draft. Add, name, reorder or remove
--     fields, choose primitive or nested types, and edit nested fields. Apply stages the schema and
--     its field order. Advanced exposes the equivalent raw schema, parsed as data without executing
--     Lua.
[1577] = "Felder bearbeiten öffnet einen grafischen Schemaentwurf. Felder hinzufügen, benennen, umsortieren oder entfernen, primitive oder verschachtelte Typen wählen und verschachtelte Felder bearbeiten. Übernehmen merkt das Schema und seine Feldreihenfolge vor. Erweitert zeigt das gleichwertige Rohschema, das als Daten eingelesen wird, ohne Lua auszuführen.",
-- 5ed7c1f2 English: Decide whether this condition currently matches.
[1578] = "Entscheiden, ob diese Bedingung aktuell zutrifft.",
-- cbb89125 English: The stored values for this condition.
[1579] = "Die gespeicherten Werte dieser Bedingung.",
-- d02f326b English: Shared data for this evaluation cycle.
[1580] = "Gemeinsame Daten für diesen Auswertungszyklus.",
-- 5e32b652 English: Evaluation start time, in seconds from GetTime().
[1581] = "Startzeit der Auswertung in Sekunden laut GetTime().",
-- dbb95241 English: True matches; false or nil does not match.
[1582] = "true trifft zu; false oder nil trifft nicht zu.",
-- 33035e0c English: Check whether the stored condition values are complete and valid.
[1583] = "Prüfen, ob die gespeicherten Bedingungswerte vollständig und gültig sind.",
-- bc51adc0 English: Rotation specialization scope.
[1584] = "Spezialisierungsbereich der Rotation.",
-- 0cb1ce78 English: True when the condition can be evaluated.
[1585] = "true, wenn die Bedingung ausgewertet werden kann.",
-- 18eb8e30 English: Describe the condition in readable words.
[1586] = "Die Bedingung in lesbaren Worten beschreiben.",
-- 4e9300c4 English: The human-readable condition summary.
[1587] = "Die lesbare Zusammenfassung der Bedingung.",
-- 7ea336df English: Build the controls used to edit this condition.
[1588] = "Die Steuerelemente zum Bearbeiten dieser Bedingung erstellen.",
-- 2010cda9 English: The condition field container supplied by the UI adapter.
[1589] = "Der vom UI-Adapter bereitgestellte Container für die Bedingungsfelder.",
-- 2209776b English: Add controls to the supplied container.
[1590] = "Steuerelemente zum bereitgestellten Container hinzufügen.",
-- ca5a0eaf English: Build the help content for this condition.
[1591] = "Den Hilfeinhalt für diese Bedingung erstellen.",
-- a2731a25 English: The help container supplied by the UI adapter.
[1592] = "Der vom UI-Adapter bereitgestellte Hilfecontainer.",
-- 96bf1d1e English: Add help content to the supplied container.
[1593] = "Hilfeinhalt zum bereitgestellten Container hinzufügen.",
-- 6738aee6 English: Initialize resources when the condition is registered.
[1594] = "Ressourcen initialisieren, wenn die Bedingung registriert wird.",
-- 49e57f5b English: The condition identifier.
[1595] = "Die Kennung der Bedingung.",
-- 46569f1f English: No return value is used.
[1596] = "Es wird kein Rückgabewert verwendet.",
-- 95a1b634 English: Release resources when the condition is removed or replaced.
[1597] = "Ressourcen freigeben, wenn die Bedingung entfernt oder ersetzt wird.",
-- 7f816072 English: Arguments
[1598] = "Argumente",
-- 16dcaa92 English: Returns
[1599] = "Rückgabewerte",
-- b92993e1 English: Field names are Lua identifiers. Choose a field type from its dropdown. Records
--     contain named fields; allowed types contain alternatives, including nested records.
[1600] = "Feldnamen sind Lua-Bezeichner. Einen Feldtyp aus seinem Auswahlmenü wählen. Datensätze enthalten benannte Felder; erlaubte Typen enthalten Alternativen, einschließlich verschachtelter Datensätze.",
-- 5f81b556 English: A container carries its nested fields. Drop into a highlighted gap. Up / Down
--     moves within the current container; Duplicate copies the complete field; the red trash can
--     deletes it.
[1601] = "Ein Container nimmt seine verschachtelten Felder mit. In eine hervorgehobene Lücke ablegen. Hoch / Runter verschiebt innerhalb des aktuellen Containers; Duplizieren kopiert das vollständige Feld; der rote Mülleimer löscht es.",
-- d24ed6ad English: The chevron hides or shows nested fields. Add field appends to that container.
--     Undo / Redo affect the draft. Apply validates and stages the schema; Cancel leaves the
--     condition unchanged. Red borders mark invalid names or incomplete types.
[1602] = "Der Pfeil blendet verschachtelte Felder aus oder ein. Feld hinzufügen hängt an diesen Container an. Rückgängig / Wiederherstellen betreffen den Entwurf. Übernehmen prüft das Schema und merkt es vor; Abbrechen lässt die Bedingung unverändert. Rote Rahmen kennzeichnen ungültige Namen oder unvollständige Typen.",
-- 521fc51f English: Packaged helper from %s.
[1603] = "Mitgelieferte Hilfsfunktion aus %s.",
-- 75e942e5 English: Functions
[1604] = "Funktionen",
-- 786697a7 English: Browse packaged helpers and edit reusable custom Lua functions.
[1605] = "Mitgelieferte Hilfsfunktionen durchsuchen und wiederverwendbare benutzerdefinierte Lua-Funktionen bearbeiten.",
-- fc6e1f0d English: Function unavailable: %s
[1606] = "Funktion nicht verfügbar: %s",
