[1610] = "Integrierte Funktion",
-- 0d1f23b5 English: Custom function
[1611] = "Benutzerdefinierte Funktion",
-- 4dcab896 English: Delete this function? Existing dependents will become unavailable.
[1612] = "Diese Funktion löschen? Bestehende abhängige Elemente werden nicht mehr verfügbar sein.",
-- 3ac00ae7 English: Deletion staged. Apply to remove this function.
[1613] = "Löschen vorgemerkt. Übernehmen, um diese Funktion zu entfernen.",
-- f2dc99c6 English: Function bindings
[1614] = "Funktionsbindungen",
-- b19e02e9 English: Alias
[1615] = "Alias",
-- e64bbf11 English: This alias is already in use.
[1616] = "Dieser Alias wird bereits verwendet.",
-- c8037103 English: Function
[1617] = "Funktion",
-- a94fd0ee English: Add binding
[1618] = "Bindung hinzufügen",
-- 327c4c8c English: Packaged source is read-only. Duplicate it to create an editable custom
--     function.
[1619] = "Mitgelieferter Quellcode ist schreibgeschützt. Duplizieren, um eine bearbeitbare benutzerdefinierte Funktion zu erstellen.",
-- 8299c5ac English: Arguments become Lua parameters. Bindings expose selected helpers under
--     explicit local aliases. Editing an alias does not rewrite your Lua body.
[1620] = "Argumente werden zu Lua-Parametern. Bindungen stellen ausgewählte Hilfsfunktionen unter ausdrücklichen lokalen Aliasen bereit. Das Bearbeiten eines Alias schreibt den Lua-Code nicht um.",
-- 47b843fc English: New function
[1621] = "Neue Funktion",
-- edb574e3 English: Describe what this function does.
[1622] = "Beschreiben, was diese Funktion tut.",
-- 0d646ec9 English: Add a function or duplicate a packaged helper to edit its source.
[1623] = "Eine Funktion hinzufügen oder eine mitgelieferte Hilfsfunktion duplizieren, um ihren Quellcode zu bearbeiten.",
-- aebc00b0 English: LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug
--     runs this buffer explicitly using the test arguments. It does not replace the saved rotation
--     or live callback.
[1624] = "LuaWorkbench bietet Bearbeitung, Vervollständigung, API-Wissen und Debugging. Debuggen führt diesen Puffer ausdrücklich mit den Testargumenten aus. Die gespeicherte Rotation oder der aktive Callback wird dadurch nicht ersetzt.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1625] = "Verbunden: eingebettete Bearbeitung, Vervollständigung, API-Wissen und Debugging.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1626] = "Das Abhängigkeitspaket vor dem Übernehmen prüfen.",
-- e0ad4daf English: Function bindings (%d)
[1627] = "Funktionsbindungen (%d)",
-- 1f10215d English: Aliases are local names in your Lua body. Changing an alias does not rewrite
--     the body.
[1628] = "Aliase sind lokale Namen im Lua-Code. Das Ändern eines Alias schreibt den Code nicht um.",
-- f81e71de English: Reuse existing
[1629] = "Vorhandene wiederverwenden",
-- c72a3c56 English: Replace existing
[1630] = "Vorhandene ersetzen",
-- 548fcd9a English: Import with new identifier
[1631] = "Mit neuer Kennung importieren",
-- 4759498a English: Create
[1632] = "Erstellen",
-- 41d342bd English: Review source
[1633] = "Quellcode prüfen",
-- 195aae02 English: Original identifier
[1634] = "Ursprüngliche Kennung",
-- 8bec02bf English: Destination identifier
[1635] = "Zielkennung",
-- 32e8d276 English: Callback
[1636] = "Callback",
-- 222b67d3 English: Include custom function dependencies
[1637] = "Abhängigkeiten von benutzerdefinierten Funktionen einschließen",
-- df750ab9 English: Review import
[1638] = "Import prüfen",
-- 454d876b English: Apply import
[1639] = "Import übernehmen",
-- b7143073 English: Function dependency bundle
[1640] = "Abhängigkeitspaket der Funktion",
-- 44fc47f3 English: Review the complete bundle before applying an import. Imported Lua can execute
--     when registered; only apply code you trust.
[1641] = "Vor dem Übernehmen eines Imports das vollständige Paket prüfen. Importiertes Lua kann bei der Registrierung ausgeführt werden; nur vertrauenswürdigen Code übernehmen.",
-- b5ca2246 English: Review each original name, destination and dependency below. Apply import saves
--     the complete reviewed bundle.
[1642] = "Unten jeden ursprünglichen Namen, jedes Ziel und jede Abhängigkeit prüfen. Import übernehmen speichert das vollständige geprüfte Paket.",
-- 0f2dd42f English: Conflict action
[1643] = "Aktion bei Konflikt",
-- 4e81098c English: Imported name
[1644] = "Importierter Name",
-- 8e818b1f English: Existing dependents
[1645] = "Bestehende abhängige Elemente",
-- 75c417a1 English: This imported definition is disabled. Its dependents remain unavailable.
[1646] = "Diese importierte Definition ist deaktiviert. Ihre abhängigen Elemente bleiben nicht verfügbar.",
-- 2643e762 English: Required functions
[1647] = "Benötigte Funktionen",
-- 103c8bbb English: Paste a bundle above, then review its original names, destinations and required
--     functions.
[1648] = "Oben ein Paket einfügen und dann seine ursprünglichen Namen, Ziele und benötigten Funktionen prüfen.",
-- 7f12e5bc English: Filter Built In or Custom helpers and search their names, identifiers or
--     descriptions. Packaged helpers show read-only source and typed documentation. Duplicate
--     creates an editable copy with a new stable identifier. Argument and return rows document the
--     Lua signature.
[1649] = "Integrierte oder benutzerdefinierte Hilfsfunktionen filtern und ihre Namen, Kennungen oder Beschreibungen durchsuchen. Mitgelieferte Hilfsfunktionen zeigen schreibgeschützten Quellcode und typisierte Dokumentation. Duplizieren erstellt eine bearbeitbare Kopie mit einer neuen stabilen Kennung. Argument- und Rückgabezeilen dokumentieren die Lua-Signatur.",
-- 812ccde3 English: Expand Function bindings to add explicit helper aliases and choose their
--     targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid
--     dependencies keep their dependents unavailable until repaired.
[1650] = "Funktionsbindungen aufklappen, um ausdrückliche Aliase für Hilfsfunktionen hinzuzufügen und ihre Ziele zu wählen. Das Ändern eines Alias schreibt den Lua-Code nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen ihre abhängigen Elemente bis zur Reparatur nicht verfügbar.",
-- 9d60841e English: Check
[1651] = "Prüfen",
-- b64ac05f English: Live
[1652] = "Live",
-- 324b134f English: Preview
[1653] = "Vorschau",
-- a31ec5d7 English: The preview failed. Use /rm errors for details.
[1654] = "Die Vorschau ist fehlgeschlagen. Details mit /rm errors anzeigen.",
-- 1c103e84 English: Test values were not saved because they are not bounded plain data.
[1655] = "Die Testwerte wurden nicht gespeichert, da sie keine begrenzten, einfachen Daten sind.",
-- c1ab4306 English: Condition check
[1656] = "Bedingungsprüfung",
-- 0fa00491 English: Fields UI preview
[1657] = "Vorschau der Feld-UI",
-- 367bba74 English: Help preview
[1658] = "Hilfevorschau",
-- 59e490f3 English: Edit detached test values below. Check validates them before evaluating. Live
--     is opt-in; test values are saved separately from the condition source.
[1659] = "Unten losgelöste Testwerte bearbeiten. Prüfen validiert sie vor der Auswertung. Live muss ausdrücklich eingeschaltet werden; Testwerte werden getrennt vom Quellcode der Bedingung gespeichert.",
-- 8b1c0e1c English: Preview runs only this callback with detached sample values. It does not save
--     or register the condition.
[1660] = "Die Vorschau führt nur diesen Callback mit losgelösten Beispielwerten aus. Die Bedingung wird dabei weder gespeichert noch registriert.",
-- 75d9602c English: Complete the source fields before checking.
[1661] = "Vor dem Prüfen die Quellfelder vervollständigen.",
-- 00454de7 English: Check could not compile the current source. Fix the source before checking
--     again.
[1662] = "Prüfen konnte den aktuellen Quellcode nicht kompilieren. Den Quellcode korrigieren und erneut prüfen.",
-- 6a255986 English: Skipped: invalid test values
[1663] = "Übersprungen: ungültige Testwerte",
-- 4607aa3d English: Validation: %s
[1664] = "Validierung: %s",
-- 436fe71b English: Passed
[1665] = "Bestanden",
-- 4c852a7e English: Evaluation: %s
[1666] = "Auswertung: %s",
-- 55a7b6a1 English: Fields UI and Help offer an explicit Preview of the current callback. Preview
--     uses detached sample values and the normal field or help renderer. It does not save,
--     register, validate or evaluate the condition. Closing it releases its controls and returns to
--     the source draft. Check syntax never runs a callback.
[1667] = "Feld-UI und Hilfe bieten eine ausdrückliche Vorschau des aktuellen Callbacks. Die Vorschau verwendet losgelöste Beispielwerte und die normale Feld- bzw. Hilfedarstellung. Sie speichert, registriert, validiert oder wertet die Bedingung nicht aus. Beim Schließen werden ihre Steuerelemente freigegeben, und es geht zurück zum Quellentwurf. Syntax prüfen führt niemals einen Callback aus.",
-- 106d8f1b English: Evaluate and Validate offer Check with the same Fields UI and detached sample
--     values. Check runs validation first, then evaluates only valid values. Results show true,
--     false or an unavailable reason. Live is opt-in and checks at most twice per second while this
--     panel is shown; closing stops it. Test values are saved separately and never enter condition
--     exports or rotation edits. Source changes run no callbacks unless you check again or enable
--     Live.
[1668] = "Auswerten und Validieren bieten Prüfen mit derselben Feld-UI und losgelösten Beispielwerten. Prüfen validiert zuerst und wertet dann nur gültige Werte aus. Die Ergebnisse zeigen true, false oder einen Grund für die Nichtverfügbarkeit. Live muss ausdrücklich eingeschaltet werden und prüft höchstens zweimal pro Sekunde, solange dieses Feld angezeigt wird; Schließen beendet es. Testwerte werden getrennt gespeichert und gelangen nie in Bedingungsexporte oder Rotationsbearbeitungen. Änderungen am Quellcode führen keine Callbacks aus, außer bei erneutem Prüfen oder aktiviertem Live.",
-- 5d331ffe English: Functions reference
[1669] = "Funktionsreferenz",
-- 64334745 English: The Functions page documents public helpers and their typed arguments, return
--     values and source. Context completion and hover use that reference; Ctrl-click a known helper
--     to open its source. Use explicit binding aliases for reusable custom helpers.
[1670] = "Die Seite Funktionen dokumentiert öffentliche Hilfsfunktionen mit ihren typisierten Argumenten, Rückgabewerten und ihrem Quellcode. Kontextvervollständigung und Mauszeiger-Tipps nutzen diese Referenz; Strg-Klick auf eine bekannte Hilfsfunktion öffnet ihren Quellcode. Für wiederverwendbare benutzerdefinierte Hilfsfunktionen ausdrückliche Bindungsaliase verwenden.",
-- 8f344bfe English: The imported definition type does not match this editor.
[1671] = "Der importierte Definitionstyp passt nicht zu diesem Editor.",
-- 91fe2974 English: Test values changed. Check again to refresh the result.
[1672] = "Die Testwerte haben sich geändert. Erneut prüfen, um das Ergebnis zu aktualisieren.",
-- 4087dcf1 English: Complete the highlighted test inputs before checking.
[1673] = "Vor dem Prüfen die hervorgehobenen Testeingaben vervollständigen.",
-- 532eaabd English: Test
[1674] = "Test",
-- e031e0df English: Run test
[1675] = "Test ausführen",
-- 312acdf1 English: Test condition
[1676] = "Bedingung testen",
-- 34fb96f5 English: Debugger output
[1677] = "Debugger-Ausgabe",
-- e376955f English: Set test values in Test before debugging Evaluate.
[1678] = "Vor dem Debuggen von Auswerten Testwerte unter Test festlegen.",
-- 427ea36c English: Debugger output uses a detached sample and the normal field or help container.
[1679] = "Die Debugger-Ausgabe verwendet ein losgelöstes Beispiel und den normalen Feld- bzw. Hilfecontainer.",
-- af624aba English: Choose test values in Fields UI, then Run test to validate and evaluate. Help
--     is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in.
[1680] = "Testwerte in der Feld-UI wählen und dann mit Test ausführen validieren und auswerten. Die Hilfe wird unter den Feldern angezeigt. Das Öffnen von Test wertet keine Standardwerte aus. Live muss ausdrücklich eingeschaltet werden.",
-- fba588f1 English: Test opens one condition-level dialog from any callback tab. It renders Fields
--     UI and Help together with detached values. Choose the fields and Run test to validate, then
--     evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and
--     stops when the dialog closes. Committed test values are available to the debugger and stay
--     separate from source, exports and rotation edits. Check syntax never runs a callback.
[1681] = "Test öffnet aus jedem Callback-Reiter einen Dialog auf Bedingungsebene. Er stellt Feld-UI und Hilfe gemeinsam mit losgelösten Werten dar. Die Felder wählen und mit Test ausführen validieren; danach werden nur gültige Werte ausgewertet. Das Öffnen des Dialogs wertet keine Standardwerte aus. Live muss ausdrücklich eingeschaltet werden und endet beim Schließen des Dialogs. Festgelegte Testwerte stehen dem Debugger zur Verfügung und bleiben von Quellcode, Exporten und Rotationsbearbeitungen getrennt. Syntax prüfen führt niemals einen Callback aus.",
-- deba1c35 English: Nullable
[1682] = "Nullbar",
-- fbf338e4 English: Add return value
[1683] = "Rückgabewert hinzufügen",
-- c75ed23e English: Lua returns multiple values in order. Each row documents one result.
[1684] = "Lua gibt mehrere Werte in fester Reihenfolge zurück. Jede Zeile dokumentiert ein Ergebnis.",
-- f968686c English: Expand code editor
[1685] = "Code-Editor vergrößern",
-- cc81db61 English: Restore code editor
[1686] = "Code-Editor wiederherstellen",
-- cb050073 English: Choose a source helper and the local name used to call it in this Lua body.
--     Renaming the local name does not rewrite code. Source modules distinguish helpers with the
--     same name.
[1687] = "Eine Quell-Hilfsfunktion und den lokalen Namen wählen, unter dem sie in diesem Lua-Code aufgerufen wird. Das Umbenennen des lokalen Namens schreibt den Code nicht um. Quellmodule unterscheiden gleichnamige Hilfsfunktionen.",
-- cfaec007 English: Local name in code
[1688] = "Lokaler Name im Code",
-- d076565e English: Source helper
[1689] = "Quell-Hilfsfunktion",
-- b49f05b5 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. Names suggest the local binding used to call them; registry identifiers stay
--     stable.
[1690] = "Funktionsnamen bestehen aus Buchstaben, Ziffern und Unterstrichen und beginnen mit einem Buchstaben oder Unterstrich. Die Namen geben die lokale Bindung vor, über die sie aufgerufen werden; Registrierungskennungen bleiben stabil.",
-- b545dd16 English: This cannot be undone.
[1691] = "Dies kann nicht rückgängig gemacht werden.",
-- f07f87d9 English: Delete this announcement?
[1692] = "Diese Ankündigung löschen?",
-- da985348 English: Type: %s
[1693] = "Typ: %s",
-- 78a0b485 English: Supported unit-token to localized unit-name lookup. Use value.unit as a key;
--     for example addon.units[value.unit]. Available tokens vary by client.
[1694] = "Unterstützte Zuordnung von Einheitenkennungen zu lokalisierten Einheitennamen. value.unit als Schlüssel verwenden, zum Beispiel addon.units[value.unit]. Die verfügbaren Kennungen hängen vom Client ab.",
-- b2a921f3 English: Supported unit-token to localized possessive unit-name lookup, such as your
--     target.
[1695] = "Unterstützte Zuordnung von Einheitenkennungen zu lokalisierten Einheitennamen im Genitiv, etwa „Ihr Ziel“.",
-- 7e1dc663 English: Rotation Master client compatibility adapter. Its methods return ordinary
--     readable results or nil with a reason when an observation is unavailable. Use a colon call,
--     or pass addon.Platform explicitly as self with a dot reference.
[1696] = "Kompatibilitätsadapter von Rotation Master für den Client. Seine Methoden liefern normale lesbare Ergebnisse oder nil mit einem Grund, wenn eine Beobachtung nicht verfügbar ist. Einen Aufruf mit Doppelpunkt verwenden oder bei einem Punktverweis addon.Platform ausdrücklich als self übergeben.",
-- bbc0cdbf English: Rotation Master spell catalog for resolving client-specific spell IDs, ranks,
--     names, icons and links.
[1697] = "Zauberkatalog von Rotation Master zum Auflösen clientspezifischer Zauber-IDs, Ränge, Namen, Symbole und Links.",
-- 18123a69 English: Utility functions explicitly bound to this condition or function. Choose a
--     completion to bind an available custom function before inserting its reference.
[1698] = "Hilfsfunktionen, die ausdrücklich an diese Bedingung oder Funktion gebunden sind. Eine Vervollständigung wählen, um eine verfügbare benutzerdefinierte Funktion zu binden, bevor ihr Verweis eingefügt wird.",
-- 16356339 English: Rotation Master custom function
[1699] = "Benutzerdefinierte Funktion von Rotation Master",
-- 902c5c44 English: Rotation Master built-in function
[1700] = "Integrierte Funktion von Rotation Master",
-- 0443c4a6 English: Rotation Master value
[1701] = "Wert von Rotation Master",
-- 1a845fe0 English: Global function (documentation unavailable on this client)
[1702] = "Globale Funktion (Dokumentation auf diesem Client nicht verfügbar)",
-- 6912e131 English: This client does not provide signature documentation for this function. No
--     arguments or return types have been inferred.
[1703] = "Dieser Client stellt keine Signaturdokumentation für diese Funktion bereit. Es wurden keine Argumente oder Rückgabetypen abgeleitet.",
-- 90092e5f English: Invoke
[1704] = "Aufruf",
-- cb214676 English: Functions are shared across profiles after Apply. Call custom utilities as
--     functions.name(...); accepting completion adds the dependency binding. Typed calls need a
--     binding under Function bindings. Built In examples show dot or colon explicitly.
[1705] = "Funktionen werden nach dem Übernehmen profilübergreifend geteilt. Benutzerdefinierte Hilfsfunktionen als functions.name(...) aufrufen; das Annehmen einer Vervollständigung fügt die Abhängigkeitsbindung hinzu. Typisierte Aufrufe benötigen eine Bindung unter Funktionsbindungen. Integrierte Beispiele zeigen Punkt oder Doppelpunkt ausdrücklich.",
-- d03262ba English: Show line numbers
[1706] = "Zeilennummern anzeigen",
-- f12fff00 English: Line-number visibility applies to every condition and function code editor.
[1707] = "Die Sichtbarkeit der Zeilennummern gilt für jeden Code-Editor für Bedingungen und Funktionen.",
-- 596578e6 English: Call a saved custom utility as functions.name(...). Accepting a completion
--     attaches its stable dependency binding; for a typed call, choose its helper under Function
--     bindings. Existing direct aliases still work. The Invoke example shows required addon dot or
--     colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1708] = "Eine gespeicherte benutzerdefinierte Hilfsfunktion als functions.name(...) aufrufen. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihre Hilfsfunktion unter Funktionsbindungen wählen. Bestehende direkte Aliase funktionieren weiterhin. Das Beispiel unter Aufruf zeigt die für integrierte Funktionen erforderliche addon-Syntax mit Punkt oder Doppelpunkt. Das Umbenennen eines Alias schreibt den Quellcode nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- 38416c88 English: Choose the editor for custom Lua conditions and functions. Show line numbers
--     applies across code editors. Built In syntax highlighting and Plain text work without another
--     addon. Automatic selects a connected provider or falls back safely. Apply saves settings;
--     editor changes take effect on reopening, and line-number visibility updates open editors.
--     LuaWorkbench and WowLua loading status is shown separately from integration availability.
[1709] = "Den Editor für benutzerdefinierte Lua-Bedingungen und -Funktionen wählen. Zeilennummern anzeigen gilt für alle Code-Editoren. Integrierte Syntaxhervorhebung und Nur Text funktionieren ohne weiteres Addon. Automatisch wählt einen verbundenen Anbieter oder greift sicher zurück. Übernehmen speichert die Einstellungen; Editoränderungen wirken beim erneuten Öffnen, und die Sichtbarkeit der Zeilennummern wird in geöffneten Editoren aktualisiert. Der Ladestatus von LuaWorkbench und WowLua wird getrennt von der Verfügbarkeit der Integration angezeigt.",
-- 50c3cb6e English: All namespaces
[1710] = "Alle Namensräume",
-- 5605815a English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and
--     Existing API preserves its original dot or colon spelling. Existing aliases still work.
--     Renaming a function or namespace does not rewrite existing code or bindings. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1711] = "Eine Hilfsfunktion als namespace.name(...) aufrufen. Integrierte Namensräume folgen den Quelldateien; benutzerdefinierte Funktionen wählen ihren Namensraum selbst. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihren qualifizierten Namen unter Funktionsbindungen hinzufügen. Namensräume liefern kein self: Das Beispiel unter Aufruf enthält einen Methodenempfänger ausdrücklich, und Bestehende API behält die ursprüngliche Schreibweise mit Punkt oder Doppelpunkt bei. Bestehende Aliase funktionieren weiterhin. Das Umbenennen einer Funktion oder eines Namensraums schreibt bestehenden Code und Bindungen nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- 66506282 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite
--     code.
[1712] = "Eine Quell-Hilfsfunktion und ihren Namen in diesem Lua-Code wählen, etwa custom.ready oder utils.getCached. Namensräume sind privat für diesen Callback. Das Umbenennen einer Bindung schreibt den Code nicht um.",
-- 5226404c English: Existing API
[1713] = "Bestehende API",
-- e572edc2 English: Name in code
[1714] = "Name im Code",
-- c4e4e7ab English: Namespace
[1715] = "Namensraum",
-- c6d86222 English: Namespaces group functions; they do not supply a receiver. Accept a completion
--     to bind the shown dotted call. For a typed call, add the same qualified name under Function
--     bindings. Method examples include the required receiver explicitly. Functions are shared
--     across profiles after Apply.
[1716] = "Namensräume gruppieren Funktionen; sie liefern keinen Empfänger. Eine Vervollständigung annehmen, um den angezeigten Aufruf mit Punkt zu binden. Für einen typisierten Aufruf denselben qualifizierten Namen unter Funktionsbindungen hinzufügen. Methodenbeispiele enthalten den erforderlichen Empfänger ausdrücklich. Funktionen werden nach dem Übernehmen profilübergreifend geteilt.",
-- 76209725 English: Private utility-function namespace. It contains only explicit bindings for this
--     callback.
[1717] = "Privater Namensraum für Hilfsfunktionen. Er enthält nur die ausdrücklichen Bindungen für diesen Callback.",
-- 481da3a7 English: Argument
[1718] = "Argument",
-- e0836fce English: Bindings (%d)
[1719] = "Bindungen (%d)",
-- 6ecb5a70 English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain
--     compatible with saved definitions. Existing aliases still work. Renaming a function or
--     namespace does not rewrite existing code or bindings. Missing, disabled or invalid
--     dependencies keep consumers unavailable.
[1720] = "Eine Hilfsfunktion als namespace.name(...) aufrufen. Integrierte Namensräume folgen den Quelldateien; benutzerdefinierte Funktionen wählen ihren Namensraum selbst. Das Annehmen einer Vervollständigung hängt ihre stabile Abhängigkeitsbindung an; für einen typisierten Aufruf ihren qualifizierten Namen unter Funktionsbindungen hinzufügen. Namensräume liefern kein self. Bei einem Punktaufruf über einen Namensraum den Methodenempfänger ausdrücklich übergeben; object:method(x) ist die Lua-Kurzform für object.method(object, x). Bestehende Addon-APIs bleiben mit gespeicherten Definitionen kompatibel. Bestehende Aliase funktionieren weiterhin. Das Umbenennen einer Funktion oder eines Namensraums schreibt bestehenden Code und Bindungen nicht um. Fehlende, deaktivierte oder ungültige Abhängigkeiten lassen die Nutzer nicht verfügbar.",
-- d35a9985 English: Changing argument or return order can break existing callers. Rotation Master
--     will not rewrite their Lua code. Continue?
[1721] = "Eine Änderung der Reihenfolge von Argumenten oder Rückgabewerten kann bestehende Aufrufer beschädigen. Rotation Master schreibt deren Lua-Code nicht um. Fortfahren?",
-- 2199cecc English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Reordering a saved function warns because positional callers may
--     need changes; RM does not rewrite call sites.
[1722] = "Auf eine Überschrift Argumente oder Rückgabewerte klicken, um sie ein- oder auszuklappen. + Argument und + Rückgabewert hängen beim Klicken an oder fügen beim Ziehen an einer hervorgehobenen Lücke ein. Eine Zeile ziehen oder Hoch / Runter verwenden, um umzusortieren; Strg-Ziehen nimmt die folgenden Zeilen mit. Der Mülleimer entfernt eine Zeile. Typ und Nullbar dokumentieren die zulässigen Werte; Beschreibung erklärt jede Eingabe bzw. jedes Ergebnis. Lua kann mehrere geordnete Ergebnisse zurückgeben. Beim Umsortieren einer gespeicherten Funktion erscheint eine Warnung, da positionsabhängige Aufrufer eventuell angepasst werden müssen; RM schreibt Aufrufstellen nicht um.",
-- 6b0143d0 English: Return
[1723] = "Rückgabewert",
-- 2584fdfb English: Changing argument order can break existing callers. Rotation Master will not
--     rewrite their Lua code. Continue?
[1724] = "Eine Änderung der Argumentreihenfolge kann bestehende Aufrufer beschädigen. Rotation Master schreibt deren Lua-Code nicht um. Fortfahren?",
-- 79fbb27b English: Changing return documentation order does not rewrite return statements or
--     existing callers. Review the Lua body and callers for the new order. Continue?
[1725] = "Eine Änderung der Reihenfolge in der Rückgabedokumentation schreibt weder return-Anweisungen noch bestehende Aufrufer um. Lua-Code und Aufrufer auf die neue Reihenfolge prüfen. Fortfahren?",
-- 2266dd0b English: Card controls
[1726] = "Kartensteuerung",
-- 1f03f52f English: Describe this value for function documentation, completion and hover help.
--     Changes remain in the draft until Apply.
[1727] = "Beschreibt diesen Wert für Funktionsdokumentation, Vervollständigung und Hover-Hilfe. Änderungen bleiben bis „Übernehmen“ im Entwurf.",
-- 9513dcfb English: Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up
--     and down move one position. Duplicate copies the argument with a unique name; the trash can
--     removes it. Reordering a saved function requires confirmation because existing callers are
--     not rewritten.
[1728] = "Karte ziehen, um Argumente neu anzuordnen; Strg-Ziehen nimmt die folgenden Argumente mit. „Nach oben“ und „Nach unten“ verschieben um eine Position. „Duplizieren“ kopiert das Argument mit einem eindeutigen Namen; der Papierkorb entfernt es. Das Umsortieren einer gespeicherten Funktion erfordert eine Bestätigung, da bestehende Aufrufer nicht umgeschrieben werden.",
-- 33f24b5d English: Drag a card to reorder return documentation; Ctrl-drag includes following
--     returns. Up and down move one position. Duplicate copies the documented return value; the
--     trash can removes it. Return order in this list does not rewrite return statements or
--     callers.
[1729] = "Karte ziehen, um die Dokumentation der Rückgabewerte neu anzuordnen; Strg-Ziehen nimmt die folgenden Rückgabewerte mit. „Nach oben“ und „Nach unten“ verschieben um eine Position. „Duplizieren“ kopiert den dokumentierten Rückgabewert; der Papierkorb entfernt ihn. Die Reihenfolge in dieser Liste ändert weder return-Anweisungen noch Aufrufer.",
-- 74057930 English: Rendered output appears here when the callback runs or steps through widget
--     creation.
[1730] = "Die gerenderte Ausgabe erscheint hier, wenn der Callback ausgeführt oder die Widget-Erstellung schrittweise durchlaufen wird.",
-- 47b50257 English: Set values in Test before running or debugging this condition.
[1731] = "Werte unter „Test“ festlegen, bevor diese Bedingung ausgeführt oder debuggt wird.",
-- 96aa8cc3 English: The argument name is the local parameter available in the Lua body. Use a valid
--     Lua identifier. Renaming this documentation does not rewrite references in the code.
[1732] = "Der Argumentname ist der lokale Parameter, der im Lua-Rumpf verfügbar ist. Einen gültigen Lua-Bezeichner verwenden. Das Umbenennen in dieser Dokumentation schreibt keine Verweise im Code um.",
-- 438e9a47 English: Type and Nullable describe the values accepted or returned by this function.
--     They document the contract; they do not rewrite or validate values in the Lua body.
[1733] = "„Typ“ und „Nullable“ beschreiben die Werte, die diese Funktion annimmt oder zurückgibt. Sie dokumentieren den Vertrag; Werte im Lua-Rumpf werden dadurch weder umgeschrieben noch geprüft.",
-- 42e8bcf1 English: Debuffs
[1734] = "Schwächungszauber",
-- e89b30aa English: Resources
[1735] = "Ressourcen",
-- 8f0d1b30 English: Pet
[1736] = "Begleiter",
-- 7c400199 English: Logic
[1737] = "Logik",
-- 9e471951 English: Environment
[1738] = "Umgebung",
-- 33b93476 English: Time
[1739] = "Zeit",
-- 66f9cfa2 English: Spell Auto-Repeat Active
[1740] = "Automatische Zauberwiederholung aktiv",
-- 35f743e1 English: Retribution (Wowhead & wowsims)
[1741] = "Vergeltung (Wowhead & wowsims)",
-- 6fc82107 English: Melee Retribution from level 1 to 70, and the default for any Paladin no other
--     premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps
--     your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges
--     only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and
--     Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to
--     you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion
--     Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a
--     separate premade.
[1742] = "Vergeltung im Nahkampf von Stufe 1 bis 70 und der Standard für jeden Paladin, zu dem keine andere integrierte Rotation passt. Eröffnet jedes Ziel mit Richturteil der Weisheit (wenig Mana) oder des Kreuzfahrers, hält Ihr bestes Siegel aufrecht (Blut oder Märtyrer, Befehl, dann Rechtschaffenheit), Kreuzfahrerstoß, richtet nur Rechtschaffenheit, Blut oder Märtyrer (oder Befehl auf ein betäubtes Ziel), Exorzismus gegen Untote und Dämonen, Weihe für drei oder mehr Gegner bei überschüssigem Mana. Hammer des Zorns bleibt Ihnen überlassen (Wowhead nutzt ihn nur gegen fliehende Ziele). Erinnerungen: Aura der Heiligkeit, der Vergeltung oder der Hingabe, ein Segen auf Sie selbst, eine Heilung nach dem Kampf, Zornige Vergeltung. Siegel-Twisting ist eine eigene integrierte Rotation.",
-- 89f00a09 English: Retribution (Icy Veins)
[1743] = "Vergeltung (Icy Veins)",
-- c68e9ea0 English: Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood
--     or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown,
--     Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy
--     levelers. Same reminders as the Wowhead variant.
[1744] = "Vergeltung nach Icy Veins, eine Alternative zur empfohlenen integrierten Vergeltungsrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers einmal pro Ziel, Siegel der Rechtschaffenheit (Befehl nur mit einer langsamen Waffe, Blut oder Märtyrer, sobald erlernt), Kreuzfahrerstoß, Hammer des Zorns und Richturteil bei Abklingzeit-Ende, Weihe gegen zwei oder mehr Gegner, Exorzismus gegen Untote und Dämonen und Heiliger Schock für Heilig-Leveler. Dieselben Erinnerungen wie die Wowhead-Variante.",
-- 85d846bd English: Retribution seal twisting
[1745] = "Vergeltung mit Siegel-Twisting",
-- 34a6a34f English: Off by default; enable it if you twist seals (level 64+, Seal of Command and
--     Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of
--     Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader
--     Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as
--     fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer;
--     latency is not accounted for.
[1746] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie Siegel twisten (ab Stufe 64, Siegel des Befehls und Blut oder Märtyrer). Eröffnet mit Richturteil des Kreuzfahrers, dann setzt jeder Schlag früh Siegel des Befehls (Rang 1) und wechselt in den letzten 0,4 Sekunden zu Blut oder Märtyrer, Kreuzfahrerstoß zwischen den Wechseln, richtet nur Blut oder Märtyrer, Exorzismus und Weihe nur als Füller und hält unter 12 % Mana Blut ohne Twisting aufrecht. Benötigt einen zuverlässigen Schlagtimer; die Latenz wird nicht berücksichtigt.",
-- 316a63c1 English: Protection (Wowhead & wowsims)
[1747] = "Schutz (Wowhead & wowsims)",
-- c9c2efbf English: Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls
--     with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or
--     three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on
--     Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield
--     except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness
--     otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom),
--     Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you.
[1748] = "Tanken für den Schutzbaum oder jeden Paladin mit aktivem Zorn der Gerechtigkeit. Zieht mit Heiligem Schild, Schild des Rächers und Richturteil; gegen ein Ziel mit zerschmetternden Schlägen (Weltboss oder drei oder mehr Stufen über Ihnen) kommt Heiliger Schild zuerst; dann Weihe, Exorzismus gegen Untote und Dämonen, Richturteil, Heiliger Schild, Heiliger Zorn gegen Gruppen von Untoten, Schild des Rächers außer gegen Ziele mit zerschmetternden Schlägen. Siegel der Weisheit gegen Gruppen bei knappem Mana, sonst Rechtschaffenheit. Erinnerungen: Zorn der Gerechtigkeit, Aura der Hingabe, Refugium (oder Könige oder Weisheit), Zornige Vergeltung, Handauflegung. Spotten und Zielwechsel bleiben Ihnen überlassen.",
-- 80b938a1 English: Protection (Icy Veins)
[1749] = "Schutz (Icy Veins)",
-- 3ae9045e English: Icy Veins' tanking, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the
--     main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown.
--     Same reminders as the Wowhead variant without Avenging Wrath.
[1750] = "Tanken nach Icy Veins, eine Alternative zur empfohlenen integrierten Schutzrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers, wenn niemand es aufrechterhält, Rechtschaffenheit (Weisheit gegen Gruppen), Weihe als Hauptquelle der Bedrohung, Richturteil, Heiliger Schild, dann Schild des Rächers und Hammer des Zorns bei Abklingzeit-Ende. Dieselben Erinnerungen wie die Wowhead-Variante, ohne Zornige Vergeltung.",
-- 9d88b75a English: Holy (Icy Veins & Wowhead)
[1751] = "Heilig (Icy Veins & Wowhead)",
-- 879586c5 English: Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or
--     Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy
--     Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise.
--     With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura,
--     Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a
--     Retribution premade instead.
[1752] = "Heilung für einen Heilig-Paladin in einer Gruppe, auf Ihr freundliches Ziel: Handauflegung oder Heiliger Schock für ein sterbendes Ziel, Reinigung des Glaubens (Läutern vor Stufe 42), Heiliger Schock in Bewegung, Heiliges Licht bei hohem Schaden, Heiliges Licht Rang 5, um Anmut des Lichts aufrechtzuerhalten, sonst Lichtblitz. Mit einem feindlichen Ziel hält sie Richturteil der Weisheit aufrecht. Erinnerungen: Aura der Konzentration, Segen der Weisheit, Göttliche Eingebung und Göttliche Gunst. Ein Heilig-Paladin im Solospiel erhält stattdessen eine integrierte Vergeltungsrotation.",
-- 2261d994 English: Holy (Wowhead tank healing)
[1753] = "Heilig (Wowhead, Tankheilung)",
-- 63b194ff English: Wowhead's raid tank healing, an alternative to the recommended Holy premade,
--     off by default: enable it and disable that one, or raise its priority. Holy Light whenever
--     your target is missing a tenth of their health, Flash of Light only for small deficits, with
--     the same emergencies, cleansing, Judgement and reminders as the blended Holy premade.
[1754] = "Schlachtzugs-Tankheilung nach Wowhead, eine Alternative zur empfohlenen integrierten Heilig-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Heiliges Licht, sobald Ihrem Ziel ein Zehntel seiner Gesundheit fehlt, Lichtblitz nur bei kleinen Defiziten, mit denselben Notfällen, Reinigungen, Richturteilen und Erinnerungen wie die kombinierte integrierte Heilig-Rotation.",
-- 4396ff42 English: Ranged DPS (wowsims)
[1755] = "Fernkampf-DPS (wowsims)",
-- 2b43c4a1 English: Levels 1–70, every spec. Pulls with Hunter's Mark, Aimed Shot and Auto Shot,
--     keeps Auto Shot running and uses melee strikes when a target reaches you. Before Steady Shot
--     it keeps your Serpent Sting up and spends mana on Aimed, Multi and Arcane Shot only while you
--     have plenty. From level 62: Multi-Shot when ready, Steady Shot straight after each Auto Shot,
--     Arcane Shot to fill the gap, Serpent Sting when solo. With three or more enemies fighting
--     you, Multi-Shot whenever it is ready. Reminds you of aspects (Viper when mana runs low, Hawk
--     again at half mana), pet care, Kill Command, major cooldowns on elites and bosses and
--     Silencing Shot. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay
--     with you.
[1756] = "Stufen 1–70, jede Spezialisierung. Zieht mit Mal des Jägers, Gezieltem Schuss und Automatischem Schuss, hält den Automatischen Schuss am Laufen und nutzt Nahkampfangriffe, wenn ein Ziel Sie erreicht. Vor Zuverlässigem Schuss hält sie Ihren Schlangenbiss aufrecht und gibt Mana für Gezielten, Mehrfach- und Arkanen Schuss nur aus, solange Sie reichlich haben. Ab Stufe 62: Mehrfachschuss, sobald bereit, Zuverlässiger Schuss direkt nach jedem Automatischen Schuss, Arkaner Schuss zum Füllen der Lücke, Schlangenbiss beim Solospiel. Wenn drei oder mehr Gegner gegen Sie kämpfen, Mehrfachschuss, sobald er bereit ist. Erinnert an Aspekte (Viper bei knappem Mana, Falke wieder bei halbem Mana), Begleiterpflege, Fass!, große Abklingzeiten gegen Elitegegner und Bosse sowie Unterdrückenden Schuss. Begleiterbefehle, Irreführung, Fallen, Salve, Nahkampf-Weaving und Totstellen bleiben Ihnen überlassen.",
-- 825c84d1 English: Ranged DPS (Wowhead)
[1757] = "Fernkampf-DPS (Wowhead)",
-- fb9ad1ee English: Levels 1–70, every spec, following Wowhead's raid advice. Same pull, melee,
--     leveling shots, multi-target Multi-Shot and reminders as the wowsims version, but once Steady
--     Shot is learned it only offers Multi-Shot and Steady Shot after each Auto Shot: no Arcane
--     Shot filler (except while moving), no Serpent Sting and no Aspect of the Viper reminder. Pet
--     commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with you. An
--     alternative to the recommended wowsims ranged premade, off by default: enable it and disable
--     that one, or raise its priority.
[1758] = "Stufen 1–70, jede Spezialisierung, nach den Schlachtzugsempfehlungen von Wowhead. Derselbe Pull, Nahkampf, dieselben Leveling-Schüsse, Mehrfachschuss gegen mehrere Ziele und Erinnerungen wie die wowsims-Version, aber sobald Zuverlässiger Schuss erlernt ist, bietet sie nach jedem Automatischen Schuss nur Mehrfachschuss und Zuverlässigen Schuss an: kein Arkaner Schuss als Füller (außer in Bewegung), kein Schlangenbiss und keine Erinnerung an Aspekt der Viper. Begleiterbefehle, Irreführung, Fallen, Salve, Nahkampf-Weaving und Totstellen bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Fernkampfrotation nach wowsims, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 469b61e4 English: Melee DPS (wowsims)
[1759] = "Nahkampf-DPS (wowsims)",
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1760] = "Stufen 1–70, jede Spezialisierung. Aus der Verstohlenheit: Konzentration, dann Fieser Trick solo oder Erdrosseln in einer Gruppe, sonst Hinterhalt (mit einem Dolch in der Waffenhand). Im Kampf: Riposte, Zerhäckseln ab zwei Combopunkten (in seinen letzten zwei Sekunden erneuert), Ausweiden auf ein Ziel kurz vor dem Tod und bei fünf Punkten Blutung, wenn sie voll wirken kann (nicht während Klingenwirbel mehrere Ziele trifft), sonst Ausweiden. Baut mit Verstümmeln oder Meucheln (Dolch) auf, wenn das Ziel Sie nicht angreift, sonst mit Blutsturz oder Finsterem Stoß. Erinnert an fehlende Gifte, Tritt, Klingenwirbel und Adrenalinrausch, Kaltblütigkeit und Entrinnen. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen.",
-- 5f9b3940 English: Melee DPS (Wowhead)
[1761] = "Nahkampf-DPS (Wowhead)",
-- 19e52877 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the wowsims version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended wowsims melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[1762] = "Stufen 1–70, jede Spezialisierung, nach Wowhead. Dieselben Eröffner aus der Verstohlenheit, Aufbauangriffe und Erinnerungen wie die wowsims-Version, aber Zerhäckseln beginnt ab einem Combopunkt und jeder Finisher mit fünf Punkten ist Ausweiden: keine Blutung. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation nach wowsims, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- d05e07b7 English: Balance
[1763] = "Gleichgewicht",
-- 8177cc43 English: Caster Balance from level 1 to 70, and the default for any Druid no other
--     premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving,
--     Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and
--     you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire
--     (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the
--     Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight,
--     Innervate when low.
[1764] = "Gleichgewicht als Zauberwirker von Stufe 1 bis 70 und der Standard für jeden Druiden, zu dem keine andere integrierte Rotation passt. Zieht mit Sternenfeuer (Zorn vor Stufe 20), Insektenschwarm und Mondfeuer in Bewegung, Feenfeuer in einer Gruppe, Hurrikan für drei oder mehr Gegner, Mondfeuer, wenn es ausgelaufen ist und Sie 30 % Mana haben, Sternenfeuer bei Anmut der Natur, Zorn gegen ein Ziel im Nahkampf, dann Sternenfeuer (Zorn, bevor es erlernt ist). Keine Empfehlungen in Katzen-, Bären- oder Reisegestalt. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Omen der Klarsicht, Mondkingestalt, Naturgewalt bei einem langen Kampf, Anregen bei wenig Mana.",
-- 9a2fa639 English: Feral (Icy Veins, Warcraft Tavern & wowsims)
[1765] = "Wilder Kampf (Icy Veins, Warcraft Tavern & wowsims)",
-- 43a0ca32 English: Cat and bear for the Feral tree, following your form. Cat: stealth opener
--     (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that
--     lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or
--     Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops,
--     Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates,
--     Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul
--     with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an
--     optional step that starts off (it needs a powershift macro).
[1766] = "Katze und Bär für den Baum Wilder Kampf, je nach Ihrer Gestalt. Katze: Eröffner aus der Verstohlenheit (Anspringen, Verheeren oder Schreddern), Feenfeuer (Tiergestalt), Zerfetzen bei vier Combopunkten auf ein Ziel, das lange genug lebt, Wilder Biss zwischen Zerfetzen ohne Freizaubern, Zerfleischen aufrechterhalten, Schreddern von hinten oder Zerfleischen/Klaue, wenn das Ziel Sie angreift. Bär: Feenfeuer, Aufschlitzen erneuert, bevor es ausläuft, Demoralisierendes Gebrüll, außer ein Ruf eines Kriegers ist aktiv, Prankenhieb gegen Gruppen, Zerfleischen, fünfmal Aufschlitzen, Prankenhieb. In Zauberergestalt schlägt sie Katzen- (oder Bären-)gestalt vor. Erinnerungen: Mal, Dornen, Omen, Zermalmen bei überschüssiger Wut, Tigerfuror vor einem Pull, Rasende Regeneration. Powershifting ist ein optionaler Schritt, der deaktiviert beginnt (er benötigt ein Powershift-Makro).",
-- 4c55a525 English: Feral (Wowhead)
[1767] = "Wilder Kampf (Wowhead)",
-- 9092413a English: Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off
--     by default: enable it and disable that one, or raise its priority. Rip whenever it is down at
--     four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears
--     spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana.
--     Otherwise the same as the Icy Veins variant.
[1768] = "Wilder Kampf nach Wowhead, eine Alternative zur empfohlenen integrierten Rotation für Wilden Kampf nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zerfetzen, sobald es fehlt, bei vier Combopunkten und Wilder Biss nur auf ein Ziel kurz vor dem Tod (kein Bite-Weaving); Bären nutzen freie globale Abklingzeiten für Aufschlitzen vor Prankenhieb. Anregen, wenn einer Katze das Mana ausgeht. Ansonsten wie die Icy-Veins-Variante.",
-- 6a3c6c77 English: Restoration
[1769] = "Wiederherstellung",
-- da5557c1 English: Healing for the Restoration tree on your friendly target (or yourself): Healing
--     Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or
--     Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then
--     Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and
--     Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility,
--     Innervate and Rebirth. Choosing whom to heal and downranking stay with you.
[1770] = "Heilung für den Baum Wiederherstellung auf Ihr freundliches Ziel (oder Sie selbst): Heilende Berührung nach Schnelligkeit der Natur, Rasche Heilung auf ein sterbendes Ziel mit Ihrer Verjüngung oder Ihrem Nachwachsen, drei rollierende Blühendes Leben im Kampf, Verjüngung und Nachwachsen, wenn sie fehlen, dann Nachwachsen im Baum des Lebens oder Heilende Berührung außerhalb davon. Ein feindliches Ziel erhält für das Solospiel Mondfeuer und Zorn. Erinnerungen: Mal, Omen, Baum des Lebens, Schnelligkeit der Natur, Gelassenheit, Anregen und Wiedergeburt. Wen Sie heilen und das Herabstufen von Rängen bleiben Ihnen überlassen.",
-- 469b61e4 English: Melee DPS (wowsims)
[1771] = "Nahkampf-DPS (wowsims)",
-- e30bf8c3 English: Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept,
--     Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is
--     learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare,
--     Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to
--     Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic
--     Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts.
--     Slam timing, stance dancing and Berserker Rage stay with you.
[1772] = "Stufen 1–70, Waffen oder Furor. Pullt mit Sturmangriff, dann Siegesrausch, Abfangen, Toben und Wirbelwind, wenn zwei oder mehr Gegner gegen Sie kämpfen (Donnerknall, bevor es erlernt ist). Mit Blutdurst oder Tödlichem Stoß: dieser Angriff, Wirbelwind bei überschüssiger Wut, Hinrichten, Überwältigen. Davor: Wirbelwind, Hinrichten, Überwältigen, Verwunden. Überschüssige Wut geht in Verwüsten oder Rüstung zerreißen, dann Kniesehne. Erinnert an Schlachtruf, Blutrausch, Heldenhaften Stoß oder Spalten zum Wutabbau, Weitreichende Stöße, Todeswunsch, Tollkühnheit und Unterbrechungen. Timing von Zerschmettern, Haltungswechsel und Berserkerwut bleiben Ihnen überlassen.",
-- 6d10d944 English: Melee DPS (Icy Veins)
[1773] = "Nahkampf-DPS (Icy Veins)",
-- c50ff4f3 English: Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and
--     leveling steps as the wowsims version, but with Mortal Strike Execute comes first, with
--     Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and
--     Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you.
--     An alternative to the recommended wowsims melee DPS premade, off by default: enable it and
--     disable that one, or raise its priority.
[1774] = "Stufen 1–70, Waffen oder Furor, nach Icy Veins. Derselbe Pull, dieselben Erinnerungen und Leveling-Schritte wie die wowsims-Version, aber mit Tödlichem Stoß kommt Hinrichten zuerst, mit Blutdurst kommt Hinrichten direkt danach, Wirbelwind folgt, ohne Wut zurückzuhalten, und Kniesehne nur bei fast voller Wut. Timing von Zerschmettern, Haltungswechsel und Berserkerwut bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation nach wowsims, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 871d5911 English: Tank (Wowhead)
[1775] = "Tank (Wowhead)",
-- 91dfa1ce English: Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge,
--     Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder
--     Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block (with
--     a shield equipped) against bosses and higher-level enemies, Heroic Strike or Cleave, Battle
--     Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other
--     utility stay with you.
[1776] = "Stufen 10–70, gewählt, solange Sie in Verteidigungshaltung sind. Schildschlag, Rache, Donnerknall und Demoralisierender Ruf werden gegen Elitegegner und Bosse aufrechterhalten, dann Verwüsten oder Rüstung zerreißen. Gegen Gruppen: zuerst Donnerknall und Demoralisierender Ruf. Erinnert an Schildblock (mit angelegtem Schild) gegen Bosse und höherstufige Gegner, Heldenhaften Stoß oder Spalten, Schlachtruf, Blutrausch, Schildhieb sowie Letztes Gefecht und Schildwall im Notfall. Spotten und andere Hilfsmittel bleiben Ihnen überlassen.",
-- ea76d926 English: Tank (Icy Veins)
[1777] = "Tank (Icy Veins)",
-- aa141592 English: Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins.
--     Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until
--     Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield
--     Block is reminded whenever your target is attacking you and you carry a shield. Taunting and
--     other utility stay with you. An alternative to the recommended Wowhead tank premade, off by
--     default: enable it and disable that one, or raise its priority.
[1778] = "Stufen 10–70, gewählt, solange Sie in Verteidigungshaltung sind, nach Icy Veins. Schildschlag, Rache, dann Verwüsten oder Rüstung zerreißen, mit Verwunden zu Kampfbeginn, bis Schildschlag erlernt ist. Gegen Gruppen: Donnerknall und gegen Elitegegner Demoralisierender Ruf. An Schildblock wird erinnert, wann immer Ihr Ziel Sie angreift und Sie einen Schild tragen. Spotten und andere Hilfsmittel bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Tankrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 3adec7ba English: Damage (Icy Veins)
[1779] = "Schaden (Icy Veins)",
-- 9b0711bb English: Damage from level 1 to 70, used whenever the healer premade does not apply.
--     Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric
--     Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is
--     wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner
--     Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is
--     cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and
--     healing stay with you.
[1780] = "Schaden von Stufe 1 bis 70, verwendet, wann immer die integrierte Heilerrotation nicht greift. Anfangs Göttliche Pein und Zauberstab, dann Gedankenschlag, Schattenwort: Schmerz, Gedankenschinden, Schattengestalt, Vampirberührung und Schattenwort: Tod, sobald Sie sie erlernen; DoTs vor Gedankenschlag; ein sterbendes Ziel wird beim Solospiel mit dem Zauberstab erledigt. Heilig- und Disziplin-Priester beim Questen erhalten Heiliges Feuer und Göttliche Pein. Erinnerungen: Inneres Feuer, Seelenstärke, Volks-Stärkungszauber, Innerer Fokus, Schattengeist. Ein Gedankenschinden nach seinem ersten Tick wird für einen bereiten Gedankenschlag abgebrochen, oder für Schattenwort: Tod über halber Gesundheit. Schilde und Heilung bleiben Ihnen überlassen.",
-- ce79d246 English: Damage (Wowhead)
[1781] = "Schaden (Wowhead)",
-- fe006eaa English: Damage after Wowhead's guides, an alternative to the recommended Icy Veins
--     damage premade, off by default: enable it and disable that one, or raise its priority. Mind
--     Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and
--     a dying target gets spells instead of the wand. Otherwise the same as the recommended
--     premade.
[1782] = "Schaden nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Schadensrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Gedankenschlag eröffnet und kommt vor dem Erneuern der DoTs, Vampirumarmung nur, wenn Ihre Gesundheit sinkt, und ein sterbendes Ziel erhält Zauber statt des Zauberstabs. Ansonsten wie die empfohlene integrierte Rotation.",
-- d0f0e9e6 English: Healer (Wowhead)
[1783] = "Heiler (Wowhead)",
-- d31781e0 English: Healing in a group when Holy or Discipline is your main talent tree. It advises
--     on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and
--     whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or
--     Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1
--     as a cheap top-up. With an enemy targeted it offers light damage.
[1784] = "Heilung in einer Gruppe, wenn Heilig oder Disziplin Ihr Haupttalentbaum ist. Sie berät zu der freundlichen Einheit, die Sie anvisieren; wen Sie heilen, entscheiden Sie. Gebet der Besserung vor Pulls und sobald bereit, Erneuerung, Machtwort: Schild im Notfall, Bannungen, Kreis der Heilung oder Gebet der Heilung bei Gruppenschaden, Verbindende Heilung, Blitzheilung und Große Heilung sowie Große Heilung Rang 1 als günstiges Auffüllen. Mit einem anvisierten Gegner bietet sie leichten Schaden an.",
-- 45321807 English: Healer (Icy Veins)
[1785] = "Heiler (Icy Veins)",
-- e31d4277 English: Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash
--     Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to
--     heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and
--     disable that one, or raise its priority.
[1786] = "Heilung in der Reihenfolge von Icy Veins: Schild, Bannungen, Verbindende Heilung, Erneuerung, Blitzheilung, Große Heilung (beliebiger Rang), Gruppenheilungen und zuletzt Gebet der Besserung. Wen Sie heilen, entscheiden Sie. Eine Alternative zur empfohlenen integrierten Heilerrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 8283f17a English: All trees (Icy Veins)
[1787] = "Alle Talentbäume (Icy Veins)",
-- da4da042 English: Every talent tree from level 1 to 70. Curse, then Unstable Affliction,
--     Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and
--     Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains
--     when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders:
--     Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and
--     Soulshatter. Fears and other curses stay with you.
[1788] = "Jeder Talentbaum von Stufe 1 bis 70. Fluch, dann Instabiles Gebrechen, Feuerbrand, Verderbnis und Lebensentzug, sobald erlernt, Schattenblitz oder Verbrennen; Procs von Einbruch der Nacht und Heimzahlen zuerst; Saat der Verderbnis, Höllenfeuer und Schattenfurie für drei oder mehr Gegner. Solo entzieht sie Leben, wenn Sie verletzt sind, nutzt Aderlass, den Zauberstab und Seelendieb oder einen Finisher auf ein sterbendes Ziel. Erinnerungen: Teufelsrüstung, Dämonenrüstung oder Dämonenhaut, Ihr Dämon, Opferung, Seelenverbindung, Fluch verstärken und Seele brechen. Furcht und andere Flüche bleiben Ihnen überlassen.",
-- e3790b25 English: Drain-tank (Wowhead)
[1789] = "Drain-Tanking (Wowhead)",
-- 522ed69f English: Warlock after Wowhead's guides, an alternative to the recommended Icy Veins
--     Warlock premade, off by default: enable it and disable that one, or raise its priority. Solo
--     it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life
--     are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon
--     Life. Otherwise the same as the recommended premade.
[1790] = "Hexenmeister nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solo betreibt sie Drain-Tanking: Blutsauger ist der Füller, sobald Ihre DoTs wirken, und Feuerbrand und Lebensentzug werden für Elitegegner aufgespart. In einer Gruppe kommt Feuerbrand immer zum Einsatz, nach Verderbnis und Lebensentzug. Ansonsten wie die empfohlene integrierte Rotation.",
-- a97bc1c7 English: Apply changes to this selected item list. Other settings keep their own Apply
--     action.
[1791] = "Änderungen an dieser ausgewählten Gegenstandsliste übernehmen. Andere Einstellungen haben ihre eigene Übernehmen-Aktion.",
-- 4cec1d75 English: Choose an item list before editing.
[1792] = "Vor dem Bearbeiten eine Gegenstandsliste wählen.",
-- 550c388b English: The item list changed elsewhere. Close and reopen it before applying.
[1793] = "Die Gegenstandsliste wurde an anderer Stelle geändert. Vor dem Übernehmen schließen und erneut öffnen.",
-- 67559dc7 English: Native settings page unavailable: %s
[1794] = "Native Einstellungsseite nicht verfügbar: %s",
-- 0f6314b0 English: The native rotation editor is unavailable.
[1795] = "Der native Rotationseditor ist nicht verfügbar.",
-- 4850b174 English: Required
[1796] = "Erforderlich",
-- 9bcec068 English: Required field references need review. Apply keeps the displayed root
--     requirements.
[1797] = "Verweise auf erforderliche Felder müssen geprüft werden. „Übernehmen“ behält die angezeigten Anforderungen der obersten Ebene.",
-- c463dfb4 English: Required root fields must have a value before this condition can run. Rename,
--     reorder and duplicate keep this flag; removing the field removes its requirement. Moving it
--     into a nested structure makes it optional. Undo restores both. Callback code is unchanged.
[1798] = "Erforderliche Felder der obersten Ebene müssen einen Wert haben, bevor diese Bedingung ausgeführt werden kann. Umbenennen, Umsortieren und Duplizieren behalten diese Markierung; das Entfernen des Feldes entfernt seine Anforderung. Das Verschieben in eine verschachtelte Struktur macht es optional. „Rückgängig“ stellt beides wieder her. Der Callback-Code bleibt unverändert.",
-- 8b8cd45b English: Copy condition description
[1799] = "Bedingungsbeschreibung kopieren",
-- b5739be0 English: This condition exceeds the supported editor limits.
[1800] = "Diese Bedingung überschreitet die unterstützten Grenzen des Editors.",
-- df58aeb6 English: Proc Glow
[1801] = "Proc-Leuchten",
-- dce1c179 English: Loop duration
[1802] = "Schleifendauer",
-- a4f0db33 English: Start burst
[1803] = "Startblitz",
