[2879] = "Positive Gegenstands-ID oder nativ erkannter Gegenstandsname/-link zum Klassifizieren.",
-- eac23024 English: Predicate that validates the proposed spell value.
[2880] = "Prädikat, das den vorgeschlagenen Zauberwert validiert.",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2881] = "Vorhandene GUID, false bei bekannter Abwesenheit oder nil, wenn nicht verfügbar.",
