-- Context: Summary of a Set Mark step in the rotation editor and its preview tooltip, e.g. "Set
--     Skull on your target".
-- %s #1: the game's name for the raid mark, e.g. "Skull"
-- %s #2: the unit phrase the condition is about, e.g. "your target" or "the Skull-marked unit"
[4053] = "%s setzen: %s",
-- 0cbd291f English: Clear the mark on %s
-- Context: Summary of a Set Mark step that removes the marker, e.g. "Clear the mark on your
--     target".
-- %s #1: the unit phrase the condition is about, e.g. "your target" or "the Skull-marked unit"
[4054] = "Markierung entfernen: %s",
-- f065d37f English: Clear the mark
-- Context: Entry of the mark dropdown of a Set Mark step: instead of a mark, remove the marker the
--     unit carries. A verb phrase.
[4055] = "Markierung entfernen",
-- 32436d10 English: Put on an action bar
[4056] = "In eine Aktionsleiste legen",
-- eb8dfba9 English: Makes a macro that presses this step's hidden button, and picks it up. Drop it
--     on an action bar slot and Rotation Master lights it while this step is advised. In a raid
--     only the leader and assistants can place marks.
[4057] = "Erstellt ein Makro, das den versteckten Button dieses Schritts drückt, und nimmt es auf. Legen Sie es auf einen Platz der Aktionsleiste, dann hebt Rotation Master ihn hervor, solange dieser Schritt empfohlen wird. In einem Schlachtzug dürfen nur der Leiter und die Assistenten Markierungen setzen.",
-- 406b0045 English: Drag the macro %s to an action bar slot.
-- Context: Message after pressing Put on an action bar: the macro is now on the mouse cursor and
--     the player has to drop it on an action bar slot.
-- %s #1: the name of the macro that was created, e.g. "RM skull/tgt"
[4058] = "Ziehen Sie das Makro %s auf einen Platz der Aktionsleiste.",
